void Check(bool p,const char*m){if(!p)throw std::runtime_error(m);}int rejected=0;
template<class F>void Reject(F f,const char*m){try{f();}catch(const std::exception&){++rejected;return;}throw std::runtime_error(m);}
Real Field(int f,const Real*x){Real r=std::sqrt(x[0]*x[0]+x[1]*x[1]+x[2]*x[2]);return .1*f+.3*x[0]*x[1]+.2*x[2]+(f+1)*.01*(r-1)+.07*(r-1)*(r-1);}
void Fill(const c::CompositeDifference&g,const c::ScriSurface&s,int f,V&volume,V&boundary){volume.assign(size_t(g.count)*f,0);boundary.resize(s.rows.size()*f);for(size_t p=0;p<g.active.size();++p)for(int a=0;a<f;++a)volume[a*g.count+g.active[p]]=Field(a,g.geometry[p].x);for(size_t p=0;p<s.rows.size();++p)for(int a=0;a<f;++a)boundary[p*f+a]=Field(a,s.rows[p].geometry.x);}
bool Equal(const S::Jets&a,const S::Jets&b,int n){for(int f=0;f<n;++f){if(a.value[f]!=b.value[f])return false;for(int i=0;i<3;++i){if(a.d[f][i]!=b.d[f][i])return false;for(int j=0;j<3;++j)if(a.dd[f][i][j]!=b.dd[f][i][j])return false;}}return true;}
// Build inverse J/H from an independently differentiated nonlinear forward map.
c::Point InversePoint(const std::array<c::Jet,3>&x){c::Point p;Real D[3][3];for(int i=0;i<3;++i){p.x[i]=x[i].f;for(int A=0;A<3;++A)D[i][A]=x[i].d[A];}Real det=D[0][0]*(D[1][1]*D[2][2]-D[1][2]*D[2][1])-D[0][1]*(D[1][0]*D[2][2]-D[1][2]*D[2][0])+D[0][2]*(D[1][0]*D[2][1]-D[1][1]*D[2][0]);for(int i=0;i<3;++i)for(int A=0;A<3;++A)p.J[A][i]=(D[(i+1)%3][(A+1)%3]*D[(i+2)%3][(A+2)%3]-D[(i+1)%3][(A+2)%3]*D[(i+2)%3][(A+1)%3])/det;for(int A=0;A<3;++A)for(int i=0;i<3;++i)for(int j=0;j<3;++j)for(int k=0;k<3;++k)for(int B=0;B<3;++B)for(int C=0;C<3;++C)p.H[A][i][j]-=p.J[A][k]*x[k].h[B][C]*p.J[B][i]*p.J[C][j];return p;}
